```typescript
import * as vscode from 'vscode';

export function activate(context: vscode.ExtensionContext) {
    const SESSION_TYPE = 'my-session-type';

    // Content provider with a requestHandler
    const contentProvider: vscode.ChatSessionContentProvider = {
        async provideChatSessionContent(resource, token) {
            console.log('provideChatSessionContent called for:', resource.toString());
            return {
                history: [],
                requestHandler: async (request, context, stream, token) => {
                    // BUG: This handler is NEVER called
                    console.log('❌ requestHandler called - THIS SHOULD RUN BUT NEVER DOES');
                    stream.markdown('Response from **requestHandler** in provideChatSessionContent');
                    return {};
                },
            };
        },
    };

    // Chat participant - this handler is ALWAYS called, even when inside a session
    const participant = vscode.chat.createChatParticipant(SESSION_TYPE, async (request, context, stream, token) => {
        console.log('✅ participant handler called - chatSessionContext:', context.chatSessionContext);
        stream.markdown('Response from **participant handler** (createChatParticipant)');

        if (context.chatSessionContext) {
            stream.markdown('\n\n⚠️ We are inside a session, but the session\'s `requestHandler` was NOT called!');
        }
        return {};
    });

    context.subscriptions.push(
        vscode.chat.registerChatSessionContentProvider(SESSION_TYPE, contentProvider, participant)
    );
}
```

**Expected behavior:**  
When sending a message inside a session editor (where `context.chatSessionContext` is defined), VS Code should call the `requestHandler` returned by `provideChatSessionContent`.

**Actual behavior:**  
VS Code always calls the chat participant's handler from `createChatParticipant`, completely ignoring the session's `requestHandler`.

**Steps to reproduce:**
1. Register the extension above
2. Open a new session editor via `workbench.action.chat.openNewSessionEditor.my-session-type` (if this works lol)
3. Send any message
4. Observe the console logs - only the participant handler is called, never the `requestHandler`

